class Vehicle {
    protected int maxSpeed = 120;

    public Vehicle(int maxSpeed) {
        this.maxSpeed = maxSpeed;
        System.out.println("Vehicle constructor executed with maxSpeed: " + maxSpeed);
    }

    public void displayStatus() {
        System.out.println("Vehicle cruising at base capability");
    }
}

class SportsCar extends Vehicle {
    protected int maxSpeed = 260; // Shadows parent's maxSpeed field

    public SportsCar(int vehicleSpeed, int sportSpeed) {
        // USE CASE 1: super(...) constructor call as FIRST statement
        super(vehicleSpeed);
        this.maxSpeed = sportSpeed;
    }

    public void compareSpeeds() {
        // USE CASE 2: super.fieldName resolves shadowed parent field
        System.out.println("Parent maxSpeed (via super): " + super.maxSpeed + " km/h");
        System.out.println("Child maxSpeed (via this): " + this.maxSpeed + " km/h");
    }

    public void testDrive() {
        // USE CASE 3: super.methodName() invokes parent method
        super.displayStatus();
        System.out.println("Engaging Turbo Boost on SportsCar!");
    }
}

public class SuperKeywordDemo {
    public static void main(String[] args) {
        SportsCar car = new SportsCar(140, 300);
        car.compareSpeeds();
        car.testDrive();
    }
}

class Base {
    public Base(String msg) { System.out.println(msg); }
}

class Sub extends Base {
    public Sub() {
        // COMPILER ERROR if uncommented:
        // System.out.println("Before super");
        super("Base initialized"); // MUST be first statement!
        System.out.println("Sub initialized");
    }
}

public class FirstStatementDemo {
    public static void main(String[] args) {
        new Sub();
    }
}

