    public static void main(String[] args) {
        Product standard = new Product();
        LuxuryProduct luxury = new LuxuryProduct();
        System.out.println("Standard Price: $" + standard.calculatePrice(1000.0));
        System.out.println("Luxury Price: $" + luxury.calculatePrice(1000.0));
    }
}

