class Order {
    protected String orderId;
    protected double amount;
    public Order(String id, double amount) {
        this.orderId = id;
        this.amount = amount;
    }
    public double processOrder() {
        return amount;
    }
}

class InternationalOrder extends Order {
    private String destinationCountry;
    private double customsDutyRate;
    public InternationalOrder(String id, double amount, String country, double dutyRate) {
        super(id, amount);
        this.destinationCountry = country;
        this.customsDutyRate = dutyRate;
    }
    public double processOrder() {
        double base = super.processOrder();
        return base + (base * customsDutyRate / 100.0);
    }
    public void displaySummary() {
        System.out.println("Order " + orderId + " Base Processed: $" + super.processOrder());
        System.out.println("International Order " + orderId + " [Destination: " + destinationCountry + "] Total with Customs: $" + processOrder());
    }
}

public class Main {
    public static void main(String[] args) {
        InternationalOrder order = new InternationalOrder("ORD-998", 2000.0, "Germany", 15.0);
        order.displaySummary();
    }
}
